async () => { /* H helpers for this script: globals, runtime state, the open board's test state, a toast spy, a phone call to a contact, and a choice picker that continues until a choice matching rx is on screen */
  const t = window.__test;
  window.__toasts = []; const orig = window.gameAlert; window.gameAlert = (...a) => { window.__toasts.push(a); return orig ? orig(...a) : undefined; };
  window.__ded = {
    g: () => window.gameState.globalVariables,
    rt: () => window.deductionRuntime && window.deductionRuntime.getState(),
    board: () => { const mg = window.MinigameFramework.currentMinigame; const s = mg && mg.getTestState && mg.getTestState(); return s && s.board && s.board.deduction; },
    toastsMatching: (rx) => (window.__toasts || []).filter(a => new RegExp(rx).test(String(a[0]))),
    pick: async (rx, ms = 15000) => { const end = Date.now() + ms; while (Date.now() < end) { const d = t.minigame.getState() && t.minigame.getState().dialogue; if (d && d.awaitingChoice && (d.choices || []).some(c => new RegExp(rx, 'i').test(c.text))) { const r = await t.minigame.choose(rx); return !(r && r.ok === false); } if (d && d.canContinue) await t.minigame.continue(); await new Promise(r => setTimeout(r, 150)); } return false; },
    call: async (name) => { const r = await t.interactInventory('phone'); if (r && r.ok === false) return false; await new Promise(r => setTimeout(r, 400)); const c = await t.minigame.clickText(name); return !(c && c.ok === false); }
  };
  return !!window.deductionRuntime && typeof window.deductionRuntime.getState === 'function'; }

async () => { /* O0 grant every clue fact from the console, so every suspect is decided */ const ids = Object.entries(window.gameScenario.social.intelFacts).filter(([k, v]) => v && v.deduction).map(([k]) => k);
  for (const id of ids) window.deductionRuntime.grantFact(id, { source: 'console' }); await new Promise(r => setTimeout(r, 500));
  return ids.length === 18 && ids.every(id => window.__ded.g()['se_intel_' + id] === true); }

async () => { /* O1 three wrong calls: a_thrown_out set, HaX rings with the warned get-out */ const end = Date.now() + 10000; while (Date.now() < end && window.__ded.g().a_thrown_out !== true) await new Promise(r => setTimeout(r, 200));
  if (window.__ded.g().a_thrown_out !== true || window.__ded.rt().state.wrongCount !== 3) return false;
  if (!window.MinigameFramework.currentMinigame) { if (!(await window.__ded.call('HaX'))) return false; if (!(await window.__ded.pick('^They.re onto me'))) return false; }
  return await window.__ded.pick('^Get out'); }

async () => { /* O3 t_a_thrown_out_end fired; credits roll with the thrown-out line; header, ticker and credits never read MISSION COMPLETE */ const g = window.__ded.g(); if (!(g.scenario_triggers_fired || {}).t_a_thrown_out_end) return false;
  const end = Date.now() + 20000; while (Date.now() < end && !(window.BondVisualiser && window.BondVisualiser.isOpen())) await new Promise(r => setTimeout(r, 250)); await new Promise(r => setTimeout(r, 1500));
  const txt = (document.querySelector('.bond-visualiser') || document.body).textContent; const tick = (document.querySelector('.bv-ticker-inner') || {}).textContent || '';
  return /You were thrown out before the ritual/.test(txt) && /CASE CLOSED/.test(txt) && !/MISSION COMPLETE/.test(txt) && !/MISSION COMPLETE|WELL PLAYED/.test(tick); }
